export function wallTemplate(s,side){const k=s.wallMount,marks=k.keyholes.map(p=>({x:p.seat[0],y:p.seat[1],label:'Винт подвеса Ø4'})).concat([{x:k.lock[0],y:k.lock[1],label:'Нижний фиксатор Ø4'}]);return `<svg xmlns="http://www.w3.org/2000/svg" width="${side+40}mm" height="${side+55}mm" viewBox="${-side/2-20} ${-side/2-20} ${side+40} ${side+55}"><rect x="${-side/2}" y="${-side/2}" width="${side}" height="${side}" fill="none" stroke="black" stroke-width=".3"/><g transform="scale(1,-1)">${marks.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="2.25" fill="none" stroke="black" stroke-width=".25"/><path d="M${p.x-4},${p.y}h8 M${p.x},${p.y-4}v8" stroke="black" stroke-width=".2"/>`).join('')}</g><g font-family="sans-serif" font-size="3.2">${marks.map(p=>`<text x="${p.x+5}" y="${-p.y+1}">${p.label}</text>`).join('')}<text x="${-side/2}" y="${side/2+9}">Печать 100%, без подгонки. Контрольная линия 50 мм:</text><path d="M0,${side/2+17}h50" stroke="black" stroke-width=".4"/><text x="${-side/2}" y="${side/2+28}">Дюбели и глубину сверления выбирайте по материалу стены.</text></g></svg>`;}
export function serviceBOM(d){const s=d.service;return {units:'mm',printedParts:d.parts.map(p=>p.name),purchased:[{item:'Прозрачная миниатюрная лампа E10',quantity:1,spec:'3.5V DC, 200mA, 0.7W, Ø12×24mm',manufacturerURL:'https://www.eitech.de/en/products/gluhlampe-3-5v-klar'},{item:'Голый двухвыводный вертикальный патрон E10',quantity:1,nominalDimensions:[s.socketDiameter,s.socketHeight],note:'Размеры корпуса, шага выводов 10mm и положения нити измерить до печати. Широкий фланец изменит тень.'},{item:'Подготовленная плата FR4',quantity:1,dimensions:s.pcbSize,mountingHoles:s.pcbMounts,pinHoles:s.pcbPinCenters,note:'Плату изготовить/просверлить по шаблону; не готовый покупной модуль.'},{item:'Внешний стабилизированный блок питания',quantity:1,spec:'Выход 3.5V DC, ≥0.3A. Сетевые части остаются снаружи.'},{item:'Изолированный двухжильный кабель + двухконтактный разъём',quantity:1,spec:`Оболочка Ø${s.wireDiameter}; разъём не более8×6mm в сечении, диагональ≤10mm; свободный запас≥${s.serviceSlackMM}mm после прижима.`},{item:'M3×16 + гайки M3',quantity:4,use:'Плита к задней панели; гайки в шестигранных карманах сзади.'},{item:'M3×10 + гайки M3',quantity:2,use:'Съёмная стойка к плите; гайки снизу плиты.'},{item:'M3×8 барашковый винт + гайка M3',quantity:1,use:'Передний съёмный экран.'},{item:'M2×6',quantity:2,use:'Прижим входного кабеля.'},{item:'M2×4',quantity:4,use:'Четыре прижима фигурных стенок.'},{item:'M2×4 + шайба0.5mm',quantity:2,use:'Плата патрона; не заменять более длинным винтом.'},{item:'M2×5 + шайба0.5mm',quantity:2,use:'Лапка экрана, винты снизу платформы.'},{item:'Винты для стены Ø4 + соответствующие дюбели',quantity:3,use:'Два подвеса и нижний фиксатор. Головки подвесов Ø6.4..8mm.'}],physicalFitTested:false,thermalTested:false};}
export function serviceReadme(d,q){const s=d.service;return `ShadowForge — обслуживаемый светильник, размеры в мм

ЭТО ЦИФРОВОЙ ПРОТОТИП: посадки, удержание резьбы в пластике, нагрев, прочность, пожарные свойства и реальная оптика ещё не испытаны.

В комплекте ${d.parts.length} печатных STL. Преобразования сборки в assembly.json; покупные детали НЕ печатать. Четыре фигурные стенки формируют общий силуэт. Передний экран52×52×3mm закрывает прямой вид на нить, оставляя боковые лучи. Его кронштейн включён в проверку и оставляет дополнительный нижний штрих. Цель — выбранный эскиз; подготовленный эскиз отличается от исходного фото.

1. Подберите прозрачную E10 3.5V/200mA/0.7W (Ø12×24mm) и голый двухвыводный патрон. Размеры патрона ${s.socketDiameter}×${s.socketHeight}mm НОМИНАЛЬНЫЕ. Измерьте расстояние от переднего края патрона до нити: сейчас${s.filamentLift}mm, оценка! Введите измеренные размеры в приложении и пересоздайте STL. Матовую/большую лампу без пересчёта не ставить.
2. Сделайте плату FR4 18×26×1.6mm: крепёж Ø2.2 в(0,±10.5); выводы Ø1.6 в(±5,0). Припаяйте патрон и короткий изолированный шлейф с разъёмом. Плюс3.5V на центральный контакт, минус на резьбовую оболочку. Пайку/оголённые контакты изолировать, разъём полностью изолированный. Проверить мультиметром и сначала включить снаружи корпуса.
3. Установите гайки M3 в задние карманы. Проведите входной кабель через открытый боковой зазор8mm. Прижим:2×M2×6; зазор${s.clampGap.toFixed(2)}mm под кабельØ${s.wireDiameter}. Сжатие0.15mm — проектное, удержание проверить натяжением. При необходимости изменить диаметр в настройках. После прижима оставить свободный сервисный запас≥${s.serviceSlackMM}mm в задней полости, не зажимать его повторно. Не укладывать кабель под отверстие нижнего фиксатора.
4. Стойку прикрутить к оптической плите2×M3×10, гайки снизу до закрытия. Протянуть шлейф с разъёмом через осевой каналØ14. Прикрепить кронштейн экрана снизу платформы2×M2×5 с шайбами0.5mm. Смонтировать плату2×M2×4 с шайбами0.5mm. Проверить отсутствие выступания винтов в плату/контакты.
5. Прикрутить оптическую плиту4×M3×16 к задним стойкам. Примерить стенки на плите, установить четыре U-прижима в задние выемки,4×M2×4. Торцы соседних стенок можно фиксировать после сухой примерки; не заливать клеем сервисные узлы. Реальную минимальную перемычку и посадки проверить в слайсере. Экран — передней плоскостью на стол, стенки — плашмя, высокий кронштейн — на боку с поддержками; остальное проверить по слоям до печати.
6. Подвес: напечатать wall-drilling-template.svg в100%, проверить линию50mm. Два винтаØ4, головкиØ6.4..8; зазор под головкой около3.6mm. Вход головкиØ9.2, опустить корпус на12mm до узкой части4.5mm. Через переднее сервисное отверстиеØ10.5 установить нижний фиксатор в стену, затем закрыть съёмной заглушкой. Дюбели, длину винтов и удержание выбрать/испытать по своей стене.
7. Вкрутить лампу и пробной тенью отцентрировать нить. Поставить M3 гайку в кронштейн, затем экран одним передним барашковым M3×8. Колба и проводка не касаются печатных деталей; номинальный зазор перед колбой10mm зависит от измеренного положения нити. Перед длительной работой измерить нагрев в собранном корпусе. Пробная печать нужна до изготовления финального комплекта.

ЗАМЕНА ЛАМПЫ: отключить внешний источник питания, дать остыть, открутить один M3 спереди, снять экран вперёд, выкрутить E10. Стенки не снимаются. ЗАМЕНА ПАТРОНА: снять экран/лампу, открутить два винта платы, вытянуть свободный шлейф и разъединить двухконтактный разъём. Не тянуть за пайку. Для доступа к прижиму/задней полости снять настенное крепление и четыре винта плиты.

ПИТАНИЕ: только внешний стабилизированный3.5V DC ≥0.3A. Нельзя напрямую подключать лампу к5V USB,12V или230V. Сетевой блок/преобразователь внутри печатной лампы не предусмотрен.

ЦИФРОВАЯ ОПТИКА: BVH-трассировка по STL + номинальным патрону, плате, винтам, разъёму и проводам; конечная нить${d.p.emitter}mm. Сходство с выбранной целью${(q.iou*100).toFixed(1)}%, контур${(q.edgeF1*100).toFixed(1)}%. Экран проверен только для фронтального конуса±40° по горизонтали/±30° по вертикали при2m. Стекло, отражения, прозрачность пластика, абсолютная яркость и тепло не моделируются. Реальный результат не гарантирован без измерений.
`;}
export function serviceHTML(d){const s=d.service;if(!s)return'';return `<h2>Замена лампы с передней стороны</h2><p>Отключить питание → снять один барашковый M3×8 → убрать экран вперёд → выкрутить E10. Четыре стенки остаются на месте. Патрон снимается с платой на двух винтах, шлейф разъединяется внутри стойки.</p><div class="service-grid"><figure><img src="assets/service/shadowforge-service-assembly.png" alt="Пример сборки"><figcaption>Пример160mm: центральный патрон и малый передний экран</figcaption></figure><figure><img src="assets/service/shadowforge-service-wiring.png" alt="Сервисная проводка"><figcaption>Разрез для осмотра: плита и стойка скрыты, показан свободный шлейф</figcaption></figure></div><ol><li><b>Ввод и проводка.</b> КабельØ${s.wireDiameter}mm входит в задний зазор8mm, удерживается отдельным прижимом. После него свободный запас≥${s.serviceSlackMM}mm и изолированный двухконтактный разъём проходят в стойкуØ14mm.</li><li><b>Патрон.</b> Голый двухвыводный E10 на подготовленной плате18×26mm. Плата крепится двумя M2, стойка — двумя M3. Размеры патрона и положение нити нужно измерить перед печатью.</li><li><b>Подвес.</b> Два замочных отверстия: надеть на головки винтовØ4, опустить на12mm. Нижний винт защищает от случайного снятия; к нему есть отверстие для отвёртки и съёмная заглушка. Шаблон сверления1:1 лежит в STL-комплекте.</li><li><b>Экран.</b> Небольшая крышечка52×52mm впереди колбы. Один кронштейн ориентирован в тёмную часть рисунка. Кронштейн оставляет дополнительный нижний штрих тени, он не вырезан из симуляции. Проверка прямого света:±40°/±30° при2m; боковые ракурсы и отражения не сертифицированы.</li></ol><p><b>Питание:</b> <a href="https://www.eitech.de/en/products/gluhlampe-3-5v-klar" target="_blank" rel="noreferrer">прозрачная E10 3.5V /0.2A /0.7W</a>, внешний стабилизированный3.5V DC ≥0.3A. Плюс — центральный контакт, минус — резьбовая оболочка. Прямое подключение к5V USB не подходит.</p><p class="hint">Изображения — пример этой конструкции при160mm. При изменении размеров точная геометрия находится во вкладке3D и вSTL. Посадки, удержание кабеля, резьба в пластике, нагрев и прочность подвеса требуют физического прототипа. Купленные детали вSTL не входят.</p>`;}
export function pcbTemplate(s){return `<svg xmlns="http://www.w3.org/2000/svg" width="40mm" height="50mm" viewBox="-20 -22 40 50"><g fill="none" stroke="black" stroke-width=".15"><rect x="-9" y="-13" width="18" height="26"/>${s.pcbMounts.map(([x,y])=>`<circle cx="${x}" cy="${-y}" r="1.1"/>`).join('')}${s.pcbPinCenters.map(([x,y])=>`<circle cx="${x}" cy="${-y}" r=".8"/>`).join('')}<path d="M-10 20H10"/></g><g font-family="sans-serif" font-size="2.3"><text x="-18" y="-17">FR4 18×26×1.6mm · 100%</text><text x="-18" y="16">КрепёжØ2.2 / выводыØ1.6</text><text x="-13" y="24">Контрольная линия20mm</text></g></svg>`;}
export function wiringDiagram(){return `<svg xmlns="http://www.w3.org/2000/svg" width="960" height="330" viewBox="0 0 960 330"><rect width="960" height="330" fill="#fff"/><g font-family="sans-serif" fill="#1f2e24" font-size="17"><text x="30" y="35" font-size="24">Подключение: только3.5V DC, ≥0.3A</text><text x="30" y="91">Внешний БП</text><text x="245" y="91">Прижим кабеля</text><text x="470" y="91">Свободный шлейф</text><text x="695" y="91">Разъём</text><text x="820" y="91">E10</text><text x="820" y="135">центр (+)</text><text x="820" y="210">резьба (−)</text><text x="30" y="280">Контакты и пайку изолировать. До установки проверить мультиметром.</text><text x="30" y="310">Не подключать напрямую к5V USB,12V или230V.</text></g><path d="M30 144H240H460C490 104 530 184 560 144H800" fill="none" stroke="#b5322e" stroke-width="4"/><path d="M30 192H240H460C490 152 530 232 560 192H800" fill="none" stroke="#263344" stroke-width="4"/><g fill="none" stroke="#59654c" stroke-width="3"><rect x="268" y="120" width="90" height="93" rx="9"/><rect x="700" y="125" width="30" height="90" rx="5"/></g></svg>`;}
